using System.Globalization;
using System.Reflection;
using System.Text.RegularExpressions;

namespace QuickTooth;

/// <summary>LowBattery: connected, with the low-battery dot.</summary>
internal enum IconState { Connected, Disconnected, LowBattery }

/// <summary>LowBattery: the low-battery dot's own short animation (not a pending action).</summary>
internal enum AnimPhase { Connecting, Landing, Disconnecting, Cancelling, LowBattery }

internal readonly record struct Rgb(byte R, byte G, byte B);

/// <summary>
/// Renders the AirPods Pro glyphs (assets/airpods-pro-*.svg, generated by tools/airpods_glyph.py)
/// at the exact small-icon size, as straight-alpha BGRA pixels. Connected = solid, with the ear tips
/// dimmed; disconnected = the reverse: hollow, dimmed body and stem with solid ear tips. Each glyph
/// carries its own per-path opacities.
/// <para>
/// Drawn by the small anti-aliasing scanline rasterizer below (no UI framework, so the app can be
/// compiled to native code): nonzero fill, 16 sub-scanlines per pixel with exact horizontal
/// coverage, clips intersected geometrically with each span. The glyphs are straight-line polygons
/// (M/L/Z), which is all tools/airpods_glyph.py emits.
/// </para>
/// </summary>
internal static partial class IconRenderer
{
    public static readonly Rgb OnDarkTaskbar = new(0xFF, 0xFF, 0xFF);   // Tunables.OnDarkTaskbar
    public static readonly Rgb OnLightTaskbar = new(0x1A, 0x1A, 0x1A);  // Tunables.OnLightTaskbar
    public static readonly Rgb Black = new(0, 0, 0);

    private readonly record struct Pt(double X, double Y);

    private readonly record struct Bounds(double Left, double Top, double Right, double Bottom)
    {
        public static readonly Bounds Empty = new(double.PositiveInfinity, double.PositiveInfinity, double.NegativeInfinity, double.NegativeInfinity);
        public Bounds Union(Bounds o) => new(Math.Min(Left, o.Left), Math.Min(Top, o.Top), Math.Max(Right, o.Right), Math.Max(Bottom, o.Bottom));
    }

    /// <summary>One &lt;path&gt; of a glyph (closed polygons), drawn at its own opacity (SVG fill-opacity) times the caller's.</summary>
    private sealed record Layer(Pt[][] Contours, double Opacity);

    /// <summary>A glyph's paths, their combined bounds, and the optional data-tracer orbit (cx cy rx ry).</summary>
    private sealed record Glyph(Layer[] Layers, Bounds Bounds, double[]? Tracer);

    private static Glyph? _fill, _line;
    private static Glyph Fill => _fill ??= ParseGlyph(ReadResource("airpods-pro-fill.svg"), "airpods-pro-fill.svg");
    private static Glyph Line => _line ??= ParseGlyph(ReadResource("airpods-pro-line.svg"), "airpods-pro-line.svg");

    /// <summary>Draws with other artwork (SVG text) until reset; null keeps/restores the built-in glyph. Simulator only.</summary>
    public static void SetGlyphs(string? fillSvg, string? lineSvg)
    {
        _fill = fillSvg != null ? ParseGlyph(fillSvg, "fill override") : null;
        _line = lineSvg != null ? ParseGlyph(lineSvg, "line override") : null;
    }

    [GeneratedRegex("<path\\b[^>]*>")] private static partial Regex PathTag();
    [GeneratedRegex("\\sd=\"([^\"]+)\"")] private static partial Regex DAttr();
    [GeneratedRegex("\\sfill-opacity=\"([^\"]+)\"")] private static partial Regex OpacityAttr();
    [GeneratedRegex("\\sdata-tracer=\"([^\"]+)\"")] private static partial Regex TracerAttr();

    private static string ReadResource(string resource)
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(resource)
            ?? throw new InvalidOperationException("missing resource " + resource);
        return new StreamReader(stream).ReadToEnd();
    }

    private static Glyph ParseGlyph(string svg, string resource)
    {
        var layers = new List<Layer>();
        var bounds = Bounds.Empty;
        foreach (Match tag in PathTag().Matches(svg))
        {
            var contours = ParsePath(DAttr().Match(tag.Value).Groups[1].Value);
            var op = OpacityAttr().Match(tag.Value);
            layers.Add(new Layer(contours, op.Success ? double.Parse(op.Groups[1].Value, CultureInfo.InvariantCulture) : 1.0));
            foreach (var c in contours)
                foreach (var p in c)
                    bounds = bounds.Union(new Bounds(p.X, p.Y, p.X, p.Y));
        }
        if (layers.Count == 0) throw new InvalidOperationException("no <path> in " + resource);
        var tr = TracerAttr().Match(svg);
        double[]? tracer = tr.Success
            ? tr.Groups[1].Value.Split(' ', StringSplitOptions.RemoveEmptyEntries).Select(v => double.Parse(v, CultureInfo.InvariantCulture)).ToArray()
            : null;
        return new Glyph(layers.ToArray(), bounds, tracer is { Length: 4 } ? tracer : null);
    }

    /// <summary>SVG path data with straight segments only: M/L/H/V/Z, absolute or relative.</summary>
    private static Pt[][] ParsePath(string d)
    {
        var contours = new List<Pt[]>();
        var cur = new List<Pt>();
        double x = 0, y = 0, startX = 0, startY = 0;
        char cmd = '\0';
        int i = 0;

        void Close()
        {
            if (cur.Count >= 3) contours.Add(cur.ToArray());
            cur.Clear();
        }
        bool NextIsNumber()
        {
            while (i < d.Length && (char.IsWhiteSpace(d[i]) || d[i] == ',')) i++;
            return i < d.Length && (char.IsDigit(d[i]) || d[i] is '-' or '+' or '.');
        }
        double Number()
        {
            NextIsNumber();
            int s = i;
            if (i < d.Length && d[i] is '-' or '+') i++;
            while (i < d.Length && (char.IsDigit(d[i]) || d[i] == '.')) i++;
            if (i < d.Length && d[i] is 'e' or 'E')
            {
                i++;
                if (i < d.Length && d[i] is '-' or '+') i++;
                while (i < d.Length && char.IsDigit(d[i])) i++;
            }
            return double.Parse(d.AsSpan(s, i - s), NumberStyles.Float, CultureInfo.InvariantCulture);
        }

        while (true)
        {
            if (!NextIsNumber())
            {
                if (i >= d.Length) break;
                cmd = d[i++];
                if (cmd is 'Z' or 'z')
                {
                    Close();
                    x = startX; y = startY;
                    continue;
                }
            }
            bool rel = char.IsLower(cmd);
            switch (char.ToUpperInvariant(cmd))
            {
                case 'M':
                {
                    double nx = Number(), ny = Number();
                    Close();
                    x = rel ? x + nx : nx; y = rel ? y + ny : ny;
                    startX = x; startY = y;
                    cur.Add(new Pt(x, y));
                    cmd = rel ? 'l' : 'L'; // further pairs are line-tos
                    break;
                }
                case 'L':
                {
                    double nx = Number(), ny = Number();
                    x = rel ? x + nx : nx; y = rel ? y + ny : ny;
                    cur.Add(new Pt(x, y));
                    break;
                }
                case 'H': { double n = Number(); x = rel ? x + n : n; cur.Add(new Pt(x, y)); break; }
                case 'V': { double n = Number(); y = rel ? y + n : n; cur.Add(new Pt(x, y)); break; }
                default:
                    throw new InvalidOperationException($"unsupported SVG path command '{cmd}' (the tray glyphs must be straight-line polygons)");
            }
        }
        Close(); // fills close open subpaths implicitly
        return contours.ToArray();
    }

    // ------------------------------------------------------------------ rasterizer

    /// <summary>Glyph units → pixels: x' = S·(x + Dx) + Tx, y' = S·y + Ty (scale and translate only).</summary>
    private readonly record struct Xf(double S, double Tx, double Ty, double Dx = 0)
    {
        public double X(double x) => S * (x + Dx) + Tx;
        public double Y(double y) => S * y + Ty;
        public Xf Offset(double dx) => this with { Dx = Dx + dx };
    }

    /// <summary>A clip in glyph units: a rectangle, optionally intersected with a circle.</summary>
    /// <summary>
    /// A clip in glyph units: a rectangle, optionally intersected with the union of equal discs (one
    /// disc for a round spot; a dense row of them for a band along a path).
    /// </summary>
    private readonly record struct Clip(double X0, double Y0, double X1, double Y1, Pt[]? Dots = null, double DotR = 0)
    {
        public static readonly Clip None = new(double.NegativeInfinity, double.NegativeInfinity, double.PositiveInfinity, double.PositiveInfinity);
        public Clip Intersect(double x0, double y0, double x1, double y1) =>
            this with { X0 = Math.Max(X0, x0), Y0 = Math.Max(Y0, y0), X1 = Math.Min(X1, x1), Y1 = Math.Min(Y1, y1) };
        public Clip WithCircle(double cx, double cy, double r) => this with { Dots = [new Pt(cx, cy)], DotR = r };
        public Clip WithDots(Pt[] dots, double r) => this with { Dots = dots, DotR = r };
    }

    private sealed class Canvas(int size)
    {
        private const int Sub = 16; // sub-scanlines per pixel row
        public readonly int Size = size;
        public readonly double[] Alpha = new double[size * size]; // single colour, so alpha is all we need
        private readonly double[] _cov = new double[size * size];
        private readonly List<(double X, int Dir)> _xs = new();
        private readonly List<(double Lo, double Hi)> _clip = new();

        public void Draw(Glyph glyph, double opacity, Xf xf, Clip clip)
        {
            foreach (var layer in glyph.Layers)
                FillPolygons(layer.Contours, Quantize(opacity * layer.Opacity), xf, clip);
        }

        /// <summary>Fills closed polygons (nonzero) at <paramref name="opacity"/>.</summary>
        public void Fill(Pt[][] contours, double opacity, Xf xf) => FillPolygons(contours, Quantize(opacity), xf, Clip.None);
        public void Fill(Pt[][] contours, double opacity, Xf xf, Clip clip) => FillPolygons(contours, Quantize(opacity), xf, clip);

        /// <summary>Clears this canvas inside a polygon (a knock-out), anti-aliased at its edge.</summary>
        public void Erase(Pt[] contour, Xf xf)
        {
            var mask = new Canvas(Size);
            mask.Fill([contour], 1, xf);
            for (int i = 0; i < Alpha.Length; i++) Alpha[i] *= 1 - Math.Min(mask.Alpha[i], 1);
        }

        /// <summary>Brush alpha as an 8-bit value, as a 32-bit ARGB brush would hold it.</summary>
        private static double Quantize(double opacity) => Math.Round(255 * Math.Clamp(opacity, 0, 1)) / 255;

        private void FillPolygons(Pt[][] contours, double alpha, Xf xf, Clip clip)
        {
            if (alpha <= 0) return;
            Array.Clear(_cov);
            // The clip in pixel space (the transform has no rotation, so rectangles and circles stay so).
            double cx0 = xf.X(clip.X0), cx1 = xf.X(clip.X1), cy0 = xf.Y(clip.Y0), cy1 = xf.Y(clip.Y1);
            var dots = clip.Dots?.Select(d => (X: xf.X(d.X), Y: xf.Y(d.Y))).ToArray();
            double dr = clip.DotR * xf.S;

            var edges = new List<(double X0, double Y0, double X1, double Y1)>();
            double minY = double.PositiveInfinity, maxY = double.NegativeInfinity;
            foreach (var c in contours)
                for (int k = 0; k < c.Length; k++)
                {
                    var a = c[k]; var b = c[(k + 1) % c.Length];
                    double ax = xf.X(a.X), ay = xf.Y(a.Y), bx = xf.X(b.X), by = xf.Y(b.Y);
                    if (ay == by) continue; // horizontal edges never cross a scanline
                    edges.Add((ax, ay, bx, by));
                    minY = Math.Min(minY, Math.Min(ay, by)); maxY = Math.Max(maxY, Math.Max(ay, by));
                }

            int rowFrom = Math.Max(0, (int)Math.Floor(Math.Max(minY, cy0)));
            int rowTo = Math.Min(Size - 1, (int)Math.Ceiling(Math.Min(maxY, cy1)));
            for (int py = rowFrom; py <= rowTo; py++)
            {
                for (int s = 0; s < Sub; s++)
                {
                    double y = py + (s + 0.5) / Sub;
                    if (y < cy0 || y >= cy1) continue;
                    double lo = Math.Max(0, cx0), hi = Math.Min(Size, cx1);
                    if (lo >= hi) continue;
                    // Where this sub-scanline is inside the clip: [lo, hi), or its overlap with the discs.
                    _clip.Clear();
                    if (dots == null)
                    {
                        _clip.Add((lo, hi));
                    }
                    else
                    {
                        foreach (var d in dots)
                        {
                            double dy = y - d.Y;
                            if (Math.Abs(dy) >= dr) continue;
                            double hw = Math.Sqrt(dr * dr - dy * dy);
                            double a = Math.Max(lo, d.X - hw), b = Math.Min(hi, d.X + hw);
                            if (a < b) _clip.Add((a, b));
                        }
                        if (_clip.Count == 0) continue;
                        _clip.Sort((p, q) => p.Lo.CompareTo(q.Lo));
                        int m = 0;
                        for (int k = 1; k < _clip.Count; k++)
                        {
                            if (_clip[k].Lo <= _clip[m].Hi) _clip[m] = (_clip[m].Lo, Math.Max(_clip[m].Hi, _clip[k].Hi));
                            else _clip[++m] = _clip[k];
                        }
                        _clip.RemoveRange(m + 1, _clip.Count - m - 1);
                    }

                    _xs.Clear();
                    foreach (var e in edges)
                    {
                        bool down = e.Y1 > e.Y0;
                        if (down ? (y < e.Y0 || y >= e.Y1) : (y < e.Y1 || y >= e.Y0)) continue;
                        _xs.Add((e.X0 + (y - e.Y0) * (e.X1 - e.X0) / (e.Y1 - e.Y0), down ? 1 : -1));
                    }
                    if (_xs.Count < 2) continue;
                    _xs.Sort((p, q) => p.X.CompareTo(q.X));

                    int winding = 0;
                    double spanStart = 0;
                    foreach (var (x, dir) in _xs)
                    {
                        int before = winding;
                        winding += dir;
                        if (before == 0 && winding != 0) spanStart = x;
                        else if (before != 0 && winding == 0)
                            foreach (var (cl, ch) in _clip) AddSpan(py, Math.Max(spanStart, cl), Math.Min(x, ch));
                    }
                }
            }

            for (int i = 0; i < Alpha.Length; i++)
            {
                double src = Math.Min(_cov[i], 1) * alpha;
                if (src > 0) Alpha[i] = src + Alpha[i] * (1 - src);
            }
        }

        /// <summary>Adds the exact horizontal coverage of [a, b) on one sub-scanline of row <paramref name="py"/>.</summary>
        private void AddSpan(int py, double a, double b)
        {
            if (b <= a) return;
            int row = py * Size;
            int first = (int)Math.Floor(a), last = Math.Min(Size - 1, (int)Math.Ceiling(b) - 1);
            for (int px = Math.Max(0, first); px <= last; px++)
                _cov[row + px] += (Math.Min(b, px + 1) - Math.Max(a, px)) / Sub;
        }

        /// <summary>Straight-alpha BGRA, top-down rows.</summary>
        public byte[] ToBgra(Rgb color)
        {
            var px = new byte[Size * Size * 4];
            for (int i = 0; i < Alpha.Length; i++)
            {
                byte a = (byte)Math.Round(255 * Math.Clamp(Alpha[i], 0, 1));
                if (a == 0) continue;
                px[i * 4] = color.B; px[i * 4 + 1] = color.G; px[i * 4 + 2] = color.R; px[i * 4 + 3] = a;
            }
            return px;
        }
    }

    /// <summary>Glyph zoom (see <see cref="Tunables.Zoom"/>).</summary>
    public static double Zoom { get => Tunables.Zoom; set => Tunables.Zoom = value; }

    /// <summary>Maps glyph units (24-unit box, centre 12,12) onto an icon of <paramref name="size"/> px at <paramref name="zoom"/>.</summary>
    private static Xf GlyphTransform(int size, double zoom)
    {
        double s = size * zoom / 24.0;
        return new Xf(s, size / 2.0 - 12 * s, size / 2.0 - 12 * s);
    }

    /// <summary>Straight-alpha BGRA, top-down rows.</summary>
    public static byte[] RenderBgra(IconState state, bool lightTaskbar, int size)
    {
        var canvas = new Canvas(size);
        canvas.Draw(state == IconState.Disconnected ? Line : Fill, 1, GlyphTransform(size, Zoom), Clip.None);
        var bgra = canvas.ToBgra(lightTaskbar ? OnLightTaskbar : OnDarkTaskbar);
        if (state != IconState.LowBattery) return bgra;

        // Low battery: an orange dot in the bottom-right corner, with a ring cut out of the artwork
        // around it (the right stem's tip) so it stands apart. Laid out on a 16-unit grid (whole units
        // = whole pixels at 16 px), scaled to the icon size.
        var grid = new Xf(size / 16.0, 0, 0);
        double r = Tunables.LowBatteryDotRadius;
        canvas.Erase(Disc(LowDotX, LowDotY, r + Tunables.LowBatteryDotGap), grid);
        var dot = new Canvas(size);
        dot.Fill([Disc(LowDotX, LowDotY, r)], 1, grid);
        return Over(canvas.ToBgra(lightTaskbar ? OnLightTaskbar : OnDarkTaskbar), dot.ToBgra(lightTaskbar ? LowOnLightTaskbar : LowOnDarkTaskbar));
    }

    public static readonly Rgb LowOnDarkTaskbar = new(0xFF, 0x8C, 0x00);   // Tunables.LowBatteryOnDark
    public static readonly Rgb LowOnLightTaskbar = new(0xCA, 0x50, 0x10);  // Tunables.LowBatteryOnLight

    // The dot's centre on the 16-unit grid: the free bottom-right corner below the right head.
    private const double LowDotX = 13.5, LowDotY = 13;

    private static Pt[] Disc(double cx, double cy, double r, int n = 48) =>
        Enumerable.Range(0, n).Select(k => new Pt(cx + r * Math.Cos(2 * Math.PI * k / n), cy + r * Math.Sin(2 * Math.PI * k / n))).ToArray();

    // ------------------------------------------------------------------ low-battery dot animation (design candidates)
    //
    // Plays when the dot first appears and again every LowBatteryReplayS; LowBatteryAnimSeconds long,
    // ending exactly on the static low-battery icon. Never repeats within one play (nothing pulses).
    //   1  pop:      the dot grows in with a slight overshoot and settles
    //   2  fill:     an orange ring appears and fills from the bottom, like the buds when they land
    //   3  glint:    a soft white highlight sweeps once across the dot
    //   4  ripple:   one thin ring spreads out from the dot and fades
    //   5  drip:     an orange drop runs down the right stem and becomes the dot

    private static readonly Rgb Glint = new(0xFF, 0xFF, 0xFF);

    private static byte[] RenderLowBatteryAnim(double u, bool lightTaskbar, int size)
    {
        if (u >= 1 || Tunables.LowBatteryAnimStyle == 0) return RenderBgra(IconState.LowBattery, lightTaskbar, size);
        var fg = lightTaskbar ? OnLightTaskbar : OnDarkTaskbar;
        var orange = lightTaskbar ? LowOnLightTaskbar : LowOnDarkTaskbar;
        var xf = GlyphTransform(size, Zoom);
        var grid = new Xf(size / 16.0, 0, 0);
        double r = Tunables.LowBatteryDotRadius, gap = Tunables.LowBatteryDotGap;
        var art = new Canvas(size);
        var dot = new Canvas(size);
        var top = new Canvas(size);      // drawn over the dot (the glint)
        var topColor = Glint;
        art.Draw(Fill, 1, xf, Clip.None);

        void Dot(double scale)
        {
            if (scale <= 0.001) return;
            art.Erase(Disc(LowDotX, LowDotY, (r + gap) * scale), grid);
            dot.Fill([Disc(LowDotX, LowDotY, r * scale)], 1, grid);
        }

        switch (Tunables.LowBatteryAnimStyle)
        {
            case 1: // pop
            {
                const double c1 = 1.3, c3 = c1 + 1;
                double v = u - 1;
                Dot(Math.Max(0, 1 + c3 * v * v * v + c1 * v * v));
                break;
            }
            case 2: // fill
            {
                double a = Clamp01(u / 0.25), f = EaseInOut(Clamp01((u - 0.2) / 0.8));
                art.Erase(Disc(LowDotX, LowDotY, r + gap), grid);
                dot.Fill([Disc(LowDotX, LowDotY, r), Disc(LowDotX, LowDotY, r - 0.75).Reverse().ToArray()], a, grid);
                double yLevel = LowDotY + r - 2 * r * f;
                if (f > 0.001) dot.Fill([Disc(LowDotX, LowDotY, r)], 1, grid, Clip.None.Intersect(-100, yLevel, 100, 100));
                break;
            }
            case 3: // glint
            {
                Dot(1);
                double cx = LowDotX - r - 1.5 + (2 * r + 3) * EaseInOut(u), w = 0.9, k = 1.2; // band leaning right
                top.Fill([[new Pt(cx - w - k, LowDotY - r), new Pt(cx + w - k, LowDotY - r), new Pt(cx + w + k, LowDotY + r), new Pt(cx - w + k, LowDotY + r)]],
                    0.8 * Math.Sin(Math.PI * u), grid, Clip.None.WithCircle(LowDotX, LowDotY, r));
                break;
            }
            case 4: // ripple
            {
                Dot(1);
                // Starts just outside the cut gap, so it never merges with the dot.
                double e = EaseOut(u), rr = r + gap + 0.4 + 3 * e, wdt = 0.8 - 0.3 * e;
                top.Fill([Disc(LowDotX, LowDotY, rr + wdt / 2), Disc(LowDotX, LowDotY, rr - wdt / 2).Reverse().ToArray()], 0.85 * (1 - u), grid);
                topColor = orange;
                break;
            }
            case 5: // drip
            {
                // 0–0.6: a drop 2.5 units long runs down the right stem (glyph x 14–18, from y 13.3 to past its tip).
                // 0.55–1: the dot grows out of the stem's tip (x 11 on the 16 grid) and rolls into the corner.
                double ud = Clamp01(u / 0.6), yEnd = 13.3 + (ArtBounds.Bottom + 2.5 - 13.3) * ud * ud;
                if (ud < 1)
                    dot.Draw(Fill, 1, xf, Clip.None.Intersect(14, Math.Max(13.3, yEnd - 2.5), 18, yEnd));
                double g = EaseOut(Clamp01((u - 0.55) / 0.45)), cx = 11 + (LowDotX - 11) * g;
                if (g > 0.001)
                {
                    art.Erase(Disc(cx, LowDotY, (r + gap) * g), grid);
                    dot.Fill([Disc(cx, LowDotY, r * g)], 1, grid);
                }
                break;
            }
        }
        var bgra = Over(art.ToBgra(fg), dot.ToBgra(orange));
        return Over(bgra, top.ToBgra(topColor));
    }

    /// <summary>Straight-alpha "source over" of <paramref name="top"/> onto <paramref name="bottom"/> (in place).</summary>
    private static byte[] Over(byte[] bottom, byte[] top)
    {
        for (int i = 0; i < bottom.Length; i += 4)
        {
            double sa = top[i + 3] / 255.0;
            if (sa == 0) continue;
            double da = bottom[i + 3] / 255.0, oa = sa + da * (1 - sa);
            for (int c = 0; c < 3; c++)
                bottom[i + c] = (byte)Math.Round((top[i + c] * sa + bottom[i + c] * da * (1 - sa)) / oa);
            bottom[i + 3] = (byte)Math.Round(255 * oa);
        }
        return bottom;
    }

    // ------------------------------------------------------------------ pending animation ("tracer")
    //
    // Connecting:    the buds spring apart, then a short glow runs around each earbud's outline (head
    //                and stem; steady brightness, never loops back to an earlier look) until the connection lands.
    // Landing:       the buds close together while the solid fills up from the bottom.
    // Disconnecting: the solid drains top-down while the buds part, then the outline settles back;
    //                if the disconnect is still pending after that, the tracer runs on the outline.
    // Cancelling:    a connect that failed: the buds glide back and the tracer fades out.
    // Every phase ends exactly on the static connected / not-connected icon.

    // Timing and shape numbers live in Tunables (AnimFrameMs, SpringSeconds, LandSeconds,
    // DisconnectSeconds, CancelSeconds, Travel, TracerPeriod, SpotRadius, Zoom).
    private static double Travel => Tunables.Travel;
    private static double TracerPeriod => Tunables.TracerPeriod;
    private static double SpotRadius => Tunables.SpotRadius;
    private static double SpringSeconds => Tunables.SpringSeconds;
    private static double LandSeconds => Tunables.LandSeconds;
    private static double DisconnectSeconds => Tunables.DisconnectSeconds;
    private static double CancelSeconds => Tunables.CancelSeconds;

    // Derived from the artwork, so a regenerated glyph needs no retuning here.
    private static Bounds ArtBounds => Fill.Bounds.Union(Line.Bounds);

    /// <summary>
    /// Zoom of the fully-apart pose: the largest at which the outermost edge, moved out by
    /// <see cref="Travel"/>, still stays inside the icon (x ≥ 0 at any size).
    /// </summary>
    private static double ApartZoom => Math.Min(Zoom, 12 / (12 - ArtBounds.Left + Travel));

    /// <summary>
    /// The tracer spot's orbit around the left head (glyph units). From the line glyph's data-tracer;
    /// without one, a circle inscribed in the left half of the artwork's head row.
    /// </summary>
    private static (double Cx, double Cy, double Rx, double Ry) Orbit
    {
        get
        {
            if (Line.Tracer is { } t) return (t[0], t[1], t[2], t[3]);
            var b = ArtBounds;
            double r = (12 - b.Left) / 2;
            return (b.Left + r, b.Top + r, r, r);
        }
    }

    /// <summary>
    /// Where the left earbud's tracer is after <paramref name="tracerT"/> seconds (glyph units): on an
    /// ellipse around the head (<see cref="Orbit"/>), one lap per <see cref="Tunables.TracerPeriod"/>.
    /// </summary>
    private static Pt TracerSpot(double tracerT)
    {
        var o = Orbit;
        double angle = 2 * Math.PI * tracerT / TracerPeriod;
        return new Pt(o.Cx + o.Rx * Math.Sin(angle), o.Cy - o.Ry * Math.Cos(angle));
    }

    /// <summary>
    /// <see cref="Tunables.TracerOutline"/> = 1: the lit stretch of the left earbud's outer outline after
    /// <paramref name="tracerT"/> seconds, as a dense row of points on the outline. It runs clockwise
    /// from the top of the head at the head orbit's speed (so a lap takes as much longer as the outline
    /// is), <see cref="Tunables.TracerLength"/> long and reaching <see cref="Tunables.TracerWidth"/>
    /// either side of the edge: narrower than the stem, so the far side of the stem stays dark.
    /// </summary>
    private static Pt[] TracerBand(double tracerT)
    {
        var o = Orbit;
        double h = Math.Pow(o.Rx - o.Ry, 2) / Math.Pow(o.Rx + o.Ry, 2);
        double orbitLength = Math.PI * (o.Rx + o.Ry) * (1 + 3 * h / (10 + Math.Sqrt(4 - 3 * h))); // Ramanujan
        var path = OutlinePath;
        double centre = tracerT * orbitLength / TracerPeriod;
        double length = Math.Min(Tunables.TracerLength, path.Length);
        int n = Math.Max(2, (int)Math.Ceiling(length / 0.2) + 1);
        var pts = new Pt[n];
        for (int k = 0; k < n; k++) pts[k] = PointAt(path, centre - length / 2 + length * k / (n - 1));
        return pts;
    }

    /// <summary>The point <paramref name="s"/> units along the closed outline (wraps around).</summary>
    private static Pt PointAt(Polyline path, double s)
    {
        s %= path.Length;
        if (s < 0) s += path.Length;
        int i = Array.BinarySearch(path.Distance, s);
        if (i < 0) i = ~i - 1;
        i = Math.Clamp(i, 0, path.Points.Length - 2);
        double u = (s - path.Distance[i]) / Math.Max(1e-9, path.Distance[i + 1] - path.Distance[i]);
        var a = path.Points[i]; var b = path.Points[i + 1];
        return new Pt(a.X + (b.X - a.X) * u, a.Y + (b.Y - a.Y) * u);
    }

    private sealed record Polyline(Pt[] Points, double[] Distance, double Length);

    private static (Glyph Source, Polyline Path)? _outline;

    /// <summary>
    /// The left earbud's outline as a closed polyline: the largest contour of the line glyph left of the
    /// centre (the body and stem; the ear tip sits on it). Starts at its top, runs clockwise on screen.
    /// </summary>
    private static Polyline OutlinePath
    {
        get
        {
            var line = Line;
            if (_outline is { } cached && cached.Source == line) return cached.Path;
            Pt[]? best = null;
            double bestArea = 0;
            foreach (var layer in line.Layers)
                foreach (var c in layer.Contours)
                {
                    if (c.Max(p => p.X) > 12) continue;
                    double area = Math.Abs(SignedArea(c));
                    if (area > bestArea) { bestArea = area; best = c; }
                }
            if (best == null) throw new InvalidOperationException("no left-earbud contour in the line glyph");

            var pts = best.ToList();
            if (SignedArea(best) < 0) pts.Reverse(); // y points down: positive shoelace area = clockwise on screen
            int top = 0;
            for (int k = 1; k < pts.Count; k++)
                if (pts[k].Y < pts[top].Y || (pts[k].Y == pts[top].Y && pts[k].X < pts[top].X)) top = k;
            var ring = pts.Skip(top).Concat(pts.Take(top)).Append(pts[top]).ToArray();
            var dist = new double[ring.Length];
            for (int k = 1; k < ring.Length; k++)
                dist[k] = dist[k - 1] + Math.Sqrt(Math.Pow(ring[k].X - ring[k - 1].X, 2) + Math.Pow(ring[k].Y - ring[k - 1].Y, 2));
            var path = new Polyline(ring, dist, dist[^1]);
            _outline = (line, path);
            return path;
        }
    }

    private static double SignedArea(Pt[] c)
    {
        double sum = 0;
        for (int k = 0; k < c.Length; k++)
        {
            var a = c[k]; var b = c[(k + 1) % c.Length];
            sum += a.X * b.Y - b.X * a.Y;
        }
        return sum / 2;
    }

    /// <summary>Has the phase played out at <paramref name="t"/> seconds (TrayController.AdvanceAnimation)?</summary>
    public static bool PhaseDone(AnimPhase phase, double t, bool stillPendingDisconnect) => phase switch
    {
        AnimPhase.Landing => t >= LandSeconds,
        AnimPhase.Cancelling => t >= CancelSeconds,
        // Plays to its end pose; if still pending after that, the tracer runs until it lands.
        AnimPhase.Disconnecting => t >= DisconnectSeconds && !stillPendingDisconnect,
        AnimPhase.Connecting => false,
        AnimPhase.LowBattery => t >= Tunables.LowBatteryAnimSeconds,
        _ => true,
    };

    private static double Clamp01(double v) => Math.Clamp(v, 0, 1);
    private static double EaseOut(double t) => 1 - Math.Pow(1 - t, 3);
    private static double EaseInOut(double t) => t < 0.5 ? 4 * t * t * t : 1 - Math.Pow(-2 * t + 2, 3) / 2;

    /// <summary>One animation frame, straight-alpha BGRA.</summary>
    /// <param name="t">Seconds since the phase started.</param>
    /// <param name="tracerT">Seconds the tracer has been running (continuous across phases).</param>
    public static byte[] RenderAnim(AnimPhase phase, double t, double tracerT, bool lightTaskbar, int size)
    {
        if (phase == AnimPhase.LowBattery) return RenderLowBatteryAnim(Clamp01(t / Tunables.LowBatteryAnimSeconds), lightTaskbar, size);
        var color = lightTaskbar ? OnLightTaskbar : OnDarkTaskbar;
        double dx, level, tracer; // bud offset, solid level (0 = none, 1 = full), tracer opacity
        switch (phase)
        {
            case AnimPhase.Connecting:
                dx = Travel * EaseOut(Clamp01(t / SpringSeconds));
                level = 0;
                tracer = Clamp01(t / 0.15);
                break;
            case AnimPhase.Landing:
            {
                double u = Clamp01(t / LandSeconds);
                dx = Travel * (1 - EaseOut(Clamp01(u / 0.5)));       // close the gap in the first half
                level = EaseInOut(Clamp01((u - 0.2) / 0.8));        // fill up from the bottom
                tracer = 1 - Clamp01(u / 0.3);
                break;
            }
            case AnimPhase.Disconnecting:
            {
                double u = Clamp01(t / DisconnectSeconds), a = Clamp01(u / 0.6);
                dx = Travel * EaseOut(a) * (1 - EaseInOut(Clamp01((u - 0.6) / 0.4))); // part, then settle back
                level = 1 - EaseInOut(a);                                          // drain top-down
                tracer = t > DisconnectSeconds ? Clamp01((t - DisconnectSeconds) / 0.15) : 0;
                tracerT = Math.Max(0, t - DisconnectSeconds);
                break;
            }
            default: // Cancelling
            {
                double u = Clamp01(t / CancelSeconds);
                dx = Travel * (1 - EaseOut(u));
                level = 0;
                tracer = 1 - u;
                break;
            }
        }

        // At rest the glyph is drawn at Zoom; apart, the buds shrink to ApartZoom, the size at
        // which the fully-apart pose still fits inside the icon without clipping.
        double poseZoom = Zoom + (ApartZoom - Zoom) * (dx / Travel);
        var art = ArtBounds;
        double yLevel = art.Bottom - level * (art.Bottom - art.Top);
        var spotLeft = TracerSpot(tracerT);
        var bandLeft = Tunables.TracerOutline >= 0.5 ? TracerBand(tracerT) : null;

        var canvas = new Canvas(size);
        var baseXf = GlyphTransform(size, poseZoom);
        foreach (var (left, offset) in new[] { (true, -dx), (false, dx) })
        {
            var xf = baseXf.Offset(offset);
            var half = Clip.None.Intersect(left ? 0 : 12, 0, left ? 12 : 24, 24); // one earbud per half

            // Above the fill line: the dim outline, plus the tracer spot.
            var above = half.Intersect(0, 0, 24, yLevel);
            canvas.Draw(Line, 1, xf, above);
            if (tracer > 0.001)
            {
                // Left spot runs clockwise, right counter-clockwise (mirrored): around each head, or along each outline.
                if (bandLeft != null)
                {
                    // A short stretch of the outline lights up; mirrored for the right earbud.
                    var band = left ? bandLeft : bandLeft.Select(p => new Pt(24 - p.X, p.Y)).ToArray();
                    canvas.Draw(Line, tracer, xf, above.WithDots(band, Tunables.TracerWidth));
                }
                else
                {
                    var spot = left ? spotLeft : new Pt(24 - spotLeft.X, spotLeft.Y);
                    canvas.Draw(Line, tracer, xf, above.WithCircle(spot.X, spot.Y, SpotRadius));
                }
            }

            // Below the fill line: solid.
            if (level > 0.001)
                canvas.Draw(Fill, 1, xf, half.Intersect(0, yLevel, 24, 24));
        }
        return canvas.ToBgra(color);
    }

    /// <summary>Large render of a whole glyph (black on white, 10 px per glyph unit) for checking the artwork.</summary>
    public static byte[] RenderLargeGlyph(bool fill, int size = 240)
    {
        var canvas = new Canvas(size);
        canvas.Draw(fill ? Fill : Line, 1, new Xf(size / 24.0, 0, 0), Clip.None);
        return canvas.ToBgra(Black);
    }
}

/// <summary>Minimal PNG writer for the check images (RGBA, stored/uncompressed deflate blocks).</summary>
internal static class Png
{
    private static readonly uint[] Crc = Enumerable.Range(0, 256).Select(n =>
    {
        uint c = (uint)n;
        for (int k = 0; k < 8; k++) c = (c & 1) != 0 ? 0xEDB88320u ^ (c >> 1) : c >> 1;
        return c;
    }).ToArray();

    public static string Save(string path, byte[] bgra, int w, int h)
    {
        var raw = new byte[h * (1 + w * 4)];
        for (int y = 0; y < h; y++)
        {
            int o = y * (1 + w * 4); // filter byte 0 (none)
            for (int x = 0; x < w; x++)
            {
                int s = (y * w + x) * 4, d = o + 1 + x * 4;
                raw[d] = bgra[s + 2]; raw[d + 1] = bgra[s + 1]; raw[d + 2] = bgra[s]; raw[d + 3] = bgra[s + 3];
            }
        }
        var z = new MemoryStream();
        z.WriteByte(0x78); z.WriteByte(0x01);
        for (int pos = 0; pos < raw.Length || pos == 0; pos += 65535)
        {
            int len = Math.Min(65535, raw.Length - pos);
            z.WriteByte((byte)(pos + len >= raw.Length ? 1 : 0));
            z.WriteByte((byte)len); z.WriteByte((byte)(len >> 8));
            z.WriteByte((byte)~len); z.WriteByte((byte)(~len >> 8));
            z.Write(raw, pos, len);
            if (raw.Length == 0) break;
        }
        uint a = 1, b = 0;
        foreach (byte v in raw) { a = (a + v) % 65521; b = (b + a) % 65521; }
        WriteBe(z, (b << 16) | a);

        using var f = File.Create(path);
        f.Write([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
        var ihdr = new MemoryStream();
        WriteBe(ihdr, (uint)w); WriteBe(ihdr, (uint)h);
        ihdr.Write([8, 6, 0, 0, 0]); // 8-bit RGBA, deflate, no filter, no interlace
        Chunk(f, "IHDR", ihdr.ToArray());
        Chunk(f, "IDAT", z.ToArray());
        Chunk(f, "IEND", []);
        return path;
    }

    private static void Chunk(Stream f, string type, byte[] data)
    {
        WriteBe(f, (uint)data.Length);
        var td = new byte[4 + data.Length];
        for (int i = 0; i < 4; i++) td[i] = (byte)type[i];
        data.CopyTo(td, 4);
        f.Write(td);
        uint c = 0xFFFFFFFFu;
        foreach (byte v in td) c = Crc[(c ^ v) & 0xFF] ^ (c >> 8);
        WriteBe(f, c ^ 0xFFFFFFFFu);
    }

    private static void WriteBe(Stream s, uint v)
    {
        s.WriteByte((byte)(v >> 24)); s.WriteByte((byte)(v >> 16)); s.WriteByte((byte)(v >> 8)); s.WriteByte((byte)v);
    }
}
